#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y) {
    int n = p.size();
    vector<int> res;
    for (int i = n-y; i < n; i++) res.push_back(p[i]);
    for (int i = x; i < n-y; i++) res.push_back(p[i]);
    for (int i = 0; i < x; i++) res.push_back(p[i]);
    p = res;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    // Place elements 1, 2, ..., n-1 in positions 0, 1, ..., n-2
    for(int placed = 0; placed < n-1; placed++){
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue;

        int rem = n - placed; // number of unplaced elements (indices placed..n-1)
        // We work on the subarray p[placed..n-1] conceptually
        // But operations work on the whole array. We need x >= placed+1 to keep first 'placed' elements fixed? No.
        // Actually we need the first 'placed' elements to stay in place. That means they must be in segment A (first x elements) and end up last. That won't preserve them.

        // Different approach: just brute force find an operation that moves pos to placed without disturbing 0..placed-1
        for(int x=1;x<n;x++) for(int y=1;x+y<n;y++){
            // Check: positions 0..placed-1 must map to themselves
            // pos_i in [0,x): maps to n-x+i
            // pos_i in [x,n-y): maps to y + (i-x)
            // pos_i in [n-y,n): maps to i-(n-y)
            bool ok = true;
            for(int i=0;i<placed&&ok;i++){
                int ni; if(i<x) ni=n-x+i; else if(i<n-y) ni=y+(i-x); else ni=i-(n-y);
                if(ni!=i) ok=false;
            }
            if(!ok) continue;
            int ni; if(pos<x) ni=n-x+pos; else if(pos<n-y) ni=y+(pos-x); else ni=pos-(n-y);
            if(ni==placed){ops.push_back({x,y});apply_op(p,x,y);goto done;}
        }
        done:;
    }

    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
